using System.Data;using System.Text.Json;using Microsoft.Data.SqlClient;using TransPort.Api.Configuration;using TransPort.Api.Modules.Abastecimiento.DTOs;using TransPort.Api.Modules.Shared.DTOs;using TransPort.Api.Modules.Shared.Repositories;
namespace TransPort.Api.Modules.Abastecimiento.Repositories;
public sealed class AbastecimientoRepository(ISqlConnectionFactory connections):IAbastecimientoRepository
{
 public async Task<IReadOnlyList<AbastecimientoListadoDto>>ListarAsync(string? estado,string? busqueda,AlcanceAbastecimiento a,CancellationToken ct){var x=new List<AbastecimientoListadoDto>();await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_abastecimiento_leer_listado");Scope(c,a);c.Parameters.Add("@Estado",SqlDbType.NVarChar,30).Value=Db(T(estado));c.Parameters.Add("@Busqueda",SqlDbType.NVarChar,200).Value=Db(T(busqueda));await using var r=await c.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))x.Add(new(r.Int64("AbastecimientoSolicitudId"),r.Text("Estado"),r.Date("FechaNecesaria"),r.Text("Motivo"),r.Int32("GiroSolicitanteId"),r.Text("GiroSolicitante"),r.Int32("SedeSolicitanteId"),r.Text("SedeSolicitante"),r.Int32("GiroProveedorId"),r.Text("GiroProveedor"),r.Int32("SedeProveedorId"),r.Text("SedeProveedor"),r.Text("Solicitante"),r.Date("FechaCreacion"),r.NullableDate("FechaModificacion"),r.Int32("Lineas")));return x;}
 public async Task<AbastecimientoDetalleDto?>ObtenerAsync(long id,AlcanceAbastecimiento a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_abastecimiento_leer_por_id");c.Parameters.Add("@Id",SqlDbType.BigInt).Value=id;Scope(c,a);await using var r=await c.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))return null;var x=new AbastecimientoDetalleDto(r.Int64("AbastecimientoSolicitudId"),r.Text("Estado"),r.Date("FechaNecesaria"),r.Text("Motivo"),r.Int32("GiroSolicitanteId"),r.Text("GiroSolicitante"),r.Int32("SedeSolicitanteId"),r.Text("SedeSolicitante"),r.Int32("GiroProveedorId"),r.Text("GiroProveedor"),r.Int32("SedeProveedorId"),r.Text("SedeProveedor"),r.Int32("SolicitanteUsuarioId"),r.Text("Solicitante"),r.Date("FechaCreacion"),r.NullableDate("FechaModificacion"),[],[]);var d=new List<AbastecimientoDetalleLineaDto>();if(await r.NextResultAsync(ct))while(await r.ReadAsync(ct))d.Add(new(r.Int64("AbastecimientoDetalleId"),r.Int32("ArticuloProveedorId"),r.Text("CodigoProveedor"),r.Text("ArticuloProveedor"),r.Int32("ArticuloDestinoId"),r.Text("CodigoDestino"),r.Text("ArticuloDestino"),Dec(r,"Cantidad"),r.Text("UnidadMedida")));var h=new List<AbastecimientoHistorialDto>();if(await r.NextResultAsync(ct))while(await r.ReadAsync(ct))h.Add(new(r.Int64("AbastecimientoHistorialId"),r.Int32("UsuarioId"),r.Text("NombreUsuario"),r.NullableText("EstadoAnterior"),r.Text("EstadoNuevo"),r.NullableText("Comentario"),r.Date("Fecha")));return x with{Detalles=d,Historial=h};}
 public async Task<AbastecimientoOpcionesDto>OpcionesAsync(AlcanceAbastecimiento a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_abastecimiento_leer_opciones");Scope(c,a);await using var r=await c.ExecuteReaderAsync(ct);var a1=await Cats(r,ct);var a2=await Next(r,ct);var a3=await Next(r,ct);var a4=await Next(r,ct);var a5=await Next(r,ct);return new(a1,a2,a3,a4,a5);}
 public async Task<long>CrearAsync(CrearAbastecimientoRequest x,AlcanceAbastecimiento a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_abastecimiento_crear");c.Parameters.Add("@GiroSolicitanteId",SqlDbType.Int).Value=x.GiroSolicitanteId;c.Parameters.Add("@SedeSolicitanteId",SqlDbType.Int).Value=x.SedeSolicitanteId;c.Parameters.Add("@GiroProveedorId",SqlDbType.Int).Value=x.GiroProveedorId;c.Parameters.Add("@SedeProveedorId",SqlDbType.Int).Value=x.SedeProveedorId;c.Parameters.Add("@FechaNecesaria",SqlDbType.Date).Value=x.FechaNecesaria.Date;c.Parameters.Add("@Motivo",SqlDbType.NVarChar,500).Value=x.Motivo.Trim();c.Parameters.Add("@Detalles",SqlDbType.NVarChar,-1).Value=JsonSerializer.Serialize(x.Detalles,new JsonSerializerOptions(JsonSerializerDefaults.Web));Scope(c,a);return Convert.ToInt64(await c.ExecuteScalarAsync(ct));}
 public async Task<bool>CambiarEstadoAsync(long id,CambiarEstadoAbastecimientoRequest x,AlcanceAbastecimiento a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_abastecimiento_actualizar_estado");c.Parameters.Add("@Id",SqlDbType.BigInt).Value=id;c.Parameters.Add("@Estado",SqlDbType.NVarChar,30).Value=x.Estado.Trim();c.Parameters.Add("@Comentario",SqlDbType.NVarChar,1000).Value=Db(T(x.Comentario));Scope(c,a);return Convert.ToInt32(await c.ExecuteScalarAsync(ct))>0;}
 public async Task ComentarAsync(long id,string comentario,AlcanceAbastecimiento a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_abastecimiento_comentar");c.Parameters.Add("@Id",SqlDbType.BigInt).Value=id;c.Parameters.Add("@Comentario",SqlDbType.NVarChar,1000).Value=comentario.Trim();Scope(c,a);await c.ExecuteNonQueryAsync(ct);}
 public async Task<bool>EliminarAsync(long id,int u,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_abastecimiento_eliminar");c.Parameters.Add("@Id",SqlDbType.BigInt).Value=id;c.Parameters.Add("@UsuarioId",SqlDbType.Int).Value=u;return Convert.ToInt32(await c.ExecuteScalarAsync(ct))>0;}
 private static async Task<IReadOnlyList<CatalogoDto>>Next(SqlDataReader r,CancellationToken ct)=>await r.NextResultAsync(ct)?await Cats(r,ct):[];private static async Task<IReadOnlyList<CatalogoDto>>Cats(SqlDataReader r,CancellationToken ct){var x=new List<CatalogoDto>();while(await r.ReadAsync(ct))x.Add(new(r.Int32("Id"),r.Text("Nombre")));return x;}private static void Scope(SqlCommand c,AlcanceAbastecimiento a){c.Parameters.Add("@UsuarioId",SqlDbType.Int).Value=a.UsuarioId;c.Parameters.Add("@EsAdministrador",SqlDbType.Bit).Value=a.EsAdministrador;}private static SqlCommand P(SqlConnection c,string n)=>new(n,c){CommandType=CommandType.StoredProcedure};private static object Db(object?x)=>x??DBNull.Value;private static string?T(string?x)=>string.IsNullOrWhiteSpace(x)?null:x.Trim();private static decimal Dec(SqlDataReader r,string n)=>r.GetDecimal(r.GetOrdinal(n));
}
